using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// End-to-end conformance test for an aomenc-encoded 128x128 all-intra clip that uses 128x128
/// superblocks and the mixed (radius-1 + radius-2) self-guided loop-restoration filter on luma. It
/// exercises the mixed/box3 self-guided path, the 64-row loop-restoration stripe stepping under 128x128
/// superblocks, the zone-2 directional corner smoothing and the 4:1 rectangular dequantisation shift.
/// The reconstructed planes match the dav1d reference (full pipeline) bit-exactly.
/// </summary>
public class Av1MixedRestorationClipDecodeTests
{
    private const string IvfBase64 = "";
    private const string ReferenceLumaBase64 = "";
    private const string ReferenceChromaUBase64 = "";
    private const string ReferenceChromaVBase64 = "";

    [Fact]
    public void Decode_MixedRestorationClip_MatchesDav1d()
    {
        using MemoryStream stream = new(Convert.FromBase64String(IvfBase64));
        Av1TileDecoder decoder = Av1DecoderCore.DecodeFirstFrame(stream);

        Assert.Equal(Convert.FromBase64String(ReferenceLumaBase64), decoder.Luma.Samples);
        Assert.Equal(Convert.FromBase64String(ReferenceChromaUBase64), decoder.ChromaU.Samples);
        Assert.Equal(Convert.FromBase64String(ReferenceChromaVBase64), decoder.ChromaV.Samples);
    }
}
